class Solution:
    def orPartners(self, nums: List[int]) -> List[int]:
        out = []
        for x in nums:
            if x % 2 == 0:
                out.append(-1)
            else:
                low = (x + 1) & ~x  # lowest 0 bit of x
                out.append(x - (low >> 1))
        return out

